from typing import Annotated, Any, Literal
from mcp.types import ToolAnnotations
from pydantic import Field

from .current_match_report import current_match_report


def register_current_match_tools(mcp, bridge):
    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=False, destructiveHint=False, openWorldHint=False))
    def fm_get_current_match(
        session_id: str,
        statistics_scope: Literal['client_snapshot', 'simulation'] = 'simulation',
        include_tactics: Annotated[bool, Field(strict=True)] = True,
        include_shot_events: Annotated[bool, Field(strict=True)] = False,
        include_player_passing: Annotated[bool, Field(strict=True)] = False,
        include_player_statistics: Annotated[bool, Field(strict=True)] = False,
        persist_host_observations: Annotated[bool, Field(strict=True)] = True,
        include_playback_events: Annotated[bool, Field(strict=True)] = False,
        playback_event_limit: Annotated[int, Field(strict=True, ge=1, le=500)] = 100,
        include_player_changes: Annotated[bool, Field(strict=True)] = False,
        player_statistics_observation_window: Annotated[bool, Field(strict=True)] = False,
    ) -> dict[str, Any]:
        """Read the currently viewable fixture, its official playback score and period, and both teams' stored tactical plans. For advice during play, prefer chance_breakdown.sides and periods, which count reconciled attempts ending before the playback cursor, with xG, on-target shots and outcomes. Use include_shot_events for coordinates and individual attempts with canonical primary event actors where the same-match original roster slot is verified. Own-goal event actors remain separate from the beneficiary; unresolved actors stay unknown. Names do not imply current on-pitch status. Optionally set include_player_passing to read same-side canonical PERSON-bound native player passes_attempted/passes_completed and a computed completion percentage. These are separately rechecked resident counter bytes with no native timestamp: statistics_scope, period and playback clocks do not align them to the displayed minute, halftime or a completed match. Unknown identities/stats stay unavailable; an actual stored zero stays zero. The population is resident slots, not a verified on-pitch lineup or complete side total. Optionally set include_player_statistics for 33 typed resident fields: attacking, tackles/interceptions/clearances, running metres/sprints, possession/pressure, crossing/dribbling, xG/xA/progression, keeper saves/discipline and aerial duels. Native byte counters can wrap; total_saves is the sum of held, parried and tipped saves modulo256. Save counts do not establish goalkeeper role or shot difficulty; incident counts do not establish chronology or eligibility, and aerial-duel labels do not establish aerial-win equivalence, opponent or location. Each row retains the same canonical identity and availability across groups; field_qualifiers preserve exact encodings, units and unsupported interpretations. These resident values are separate from playback-scoped chance events; no native timestamp, displayed-minute/halftime/full-match alignment, active participation or complete side totals is established. Unknown rows remain unknown and real zeros remain zero. ChancesCreated is an individual native property, not a proved shot-supply sequence. A null side, period or score is unknown. team_statistics are cumulative counters: by default (statistics_scope=simulation) the engine's statistics object, which is the one the match screen's statistics panel reads; statistics_scope=client_snapshot reads a copy held by the match client, refreshed at moments the reader does not know and observed both behind and ahead of the screen. While the match runs the engine is ahead of the picture, so either can include play just beyond the viewing position; chance_breakdown counts only events before the playback cursor. Tactics describe current resident settings. Kickoff settings, tactical change history and causal effects require separate evidence. By default, verified native period reads also persist bounded private host period/spatial observations for later exact retained-result linkage; host_period_capture reports success or a reason without changing the live result. Set persist_host_observations=false when no host observation files may be created: both automatic stores and their context/index writes are skipped, with disabled_by_request capture reasons. Set include_playback_events for the latest playback_event_limit (default 100, maximum 500) official native commentary event rows in storage order: raw PlayerID fields and side bits, commentary-event code, TimeSlice and duration, flags, importances and Data1, with canonical person labels only where the same fixture's original side/roster slot and native MATCH_INFO UID setup agree. It does not say which PlayerID field is the subject or a substitution on/off role, whether history is complete, who is on the pitch, or how a TimeSlice relates to the playback cursor or displayed minute. Set include_player_changes for typed native SUBSTITUTION and PLAYER_PUT_ON rows plus removal requests (PLAYER_TAKEN_OFF, SEND_OFF_PLAYER, INJURE_PLAYER) with original side/slot, native change clock when set and canonical person labels. The change vector can hold pending or archived changes, so execution, order, completeness, fixed-frame playing intervals and an active XI are not inferred; PLAYER_PUT_ON is not a starting-XI label and INJURE_PLAYER has an empty native apply body. Both blocks are physically reselected non-atomically with the rest of the read, and an advancing or unsupported source returns an unavailable state with null rows, never an empty list. Returned match, tactics, shot events and optional resident statistics retain the same source checks. No background capture or new configuration is required. No saved-file fallback. Optionally set player_statistics_observation_window=true (requires include_player_statistics=true; shot events and passing must be false) for a separate player-only result: the same 33 typed resident fields are read as fresh contiguous per-row blocks after all lifetime callbacks, with each row's own ordered host monotonic start/end interval in row_observations and an overall host_observation_window. Fixture, canonical identity/ownership and native source code stay strictly rechecked, but dynamic values may advance after their observation and are never rechecked unchanged; this relaxes the default strict byte-stability contract. Host intervals are not native clocks or displayed minutes, rows and fields need not share an instant, a memory copy is not asserted atomic, and overlapping or shared stats storage is rejected. Unknown rows stay null and zero stays zero; no chances, tactics, passing, team statistics, host observation files, native calls or game writes. Current on-pitch membership, side totals, halftime/full-match alignment, deltas and live-versus-replay remain unproved. For a completed match after the client closes, discover the exact retained result and query its stats and maps."""

        # Native playback options are forwarded only when requested, so the legacy call is unchanged.
        native_options = {}
        if include_playback_events:
            native_options.update(include_playback_events=True, playback_event_limit=playback_event_limit)
        if include_player_changes:
            native_options['include_player_changes'] = True
        if player_statistics_observation_window:
            native_options['player_statistics_observation_window'] = True
        return current_match_report(bridge, session_id, statistics_scope, include_tactics, include_shot_events, include_player_passing, include_player_statistics,
                                    persist_host_observations=persist_host_observations, **native_options)
